export { anatomy, type LinkPart, parts } from "./link.anatomy";
export { connect } from "./link.connect";
export { getRootEl, getRootId } from "./link.dom";
export { machine } from "./link.machine";
export type {
  LinkApi,
  LinkCurrent,
  LinkMachineProps,
  LinkPressDetails,
  LinkSchema,
  LinkUnderline,
  LinkVariant,
  ResolvedLinkMachineProps,
} from "./link.types";

import { type Anatomy, type AnatomyPart, createAnatomy } from "../../machine/anatomy";

export type LinkPart = "root" | "externalIcon" | "externalLabel";

export const anatomy: Anatomy<LinkPart> = createAnatomy("link").parts(
  "root",
  "externalIcon",
  "externalLabel",
);

export const parts: Record<LinkPart, AnatomyPart> = anatomy.build();

/**
 * Pure, DOM-free, replayable on a server.
 *
 * Two decisions live here rather than in the machine. Disabled means the href is
 * *stripped*, not prevented: a prevented click can be reached around (middle
 * click, the context menu), an absent href cannot — the `preventDefault` in
 * `onClick` is only the belt over that strip, for a router composition whose own
 * `href`/`to` the connect cannot remove. And the keyboard listens to Enter
 * alone, never Space: on a link Space must keep scrolling the page, and
 * intercepting it would be an APG bug, not a feature.
 */

import { ariaAttr, dataAttr } from "../../dom/attrs";
import type { NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import { isFocusVisibleModality } from "../../nav";
import { parts } from "./link.anatomy";
import { getRootId } from "./link.dom";
import type { LinkApi, LinkSchema } from "./link.types";

export function connect<T extends PropTypes>(
  service: Service<LinkSchema>,
  normalize: NormalizeProps<T>,
): LinkApi<T> {
  const { context, prop, state, send, scope } = service;

  const disabled = prop("disabled");
  const external = prop("external");
  const nativeLink = prop("nativeLink");
  const current = prop("current");
  const focusableWhenDisabled = prop("focusableWhenDisabled");
  const pressed = context.get("pressed");
  // The source is read once, when focus lands, and held: the modality of `now`
  // flips to pointer after 300ms of mouse movement whether or not the focus
  // moved, and a ring that blinks out under the user's hands was the result.
  const focusSource = state.matches("focused") ? context.get("focusSource") : null;
  const focusVisible = focusSource !== null && isFocusVisibleModality(focusSource);

  // One spelling for both attributes, so the sheet can select `[data-current]`
  // as well as `[data-current="page"]`.
  const currentAttr = current === false ? undefined : current === true ? "true" : current;

  // A native link leaves the tab order through the stripped href; only the
  // disabled-but-reachable case needs a tab index at all. A substituted element
  // has no native tab order to lose, so it is handed one — and taken out of it
  // by hand while disabled.
  const tabIndex = nativeLink
    ? disabled && focusableWhenDisabled
      ? 0
      : undefined
    : disabled && !focusableWhenDisabled
      ? -1
      : 0;

  return {
    disabled,
    external,
    current,
    pressed,
    focusSource,
    focusVisible,

    getRootProps: (): T["a"] =>
      normalize.a({
        ...parts.root.attrs,
        id: getRootId(scope),
        dir: prop("dir"),
        href: disabled ? undefined : prop("href"),
        target: prop("target") ?? (external ? "_blank" : undefined),
        rel: prop("rel") ?? (external ? "noopener noreferrer" : undefined),
        // An `<a>` without an href has no link role left, and a substituted
        // element never had one.
        role: nativeLink && !disabled ? undefined : "link",
        tabIndex,
        "aria-disabled": ariaAttr(disabled),
        "aria-current": currentAttr,
        "data-variant": prop("variant"),
        "data-underline": prop("underline"),
        "data-external": dataAttr(external),
        "data-current": currentAttr,
        "data-disabled": dataAttr(disabled),
        "data-pressed": dataAttr(pressed),
        "data-focus-visible": dataAttr(focusVisible),
        "data-focus-source": focusSource ?? undefined,
        onClick(event) {
          if (event.defaultPrevented) return;
          if (disabled) {
            event.preventDefault();
            return;
          }
          send({ type: "ROOT.CLICK", originalEvent: event });
        },
        onKeyDown(event) {
          if (event.defaultPrevented || event.repeat || event.key !== "Enter") return;
          if (disabled) {
            event.preventDefault();
            return;
          }
          send({ type: "ROOT.PRESS_START" });
          // Only a substituted root, where Enter produces no native click —
          // on a real `<a>` the browser's own click arrives as ROOT.CLICK.
          if (!nativeLink) send({ type: "ROOT.PRESS", originalEvent: event });
        },
        onKeyUp(event) {
          if (event.defaultPrevented || event.key !== "Enter") return;
          send({ type: "ROOT.PRESS_END" });
        },
        onFocus(event) {
          if (event.defaultPrevented) return;
          send({ type: "ROOT.FOCUS" });
        },
        onBlur(event) {
          if (event.defaultPrevented) return;
          send({ type: "ROOT.BLUR" });
        },
      }),

    getExternalIconProps: (): T["element"] =>
      normalize.element({
        ...parts.externalIcon.attrs,
        "aria-hidden": ariaAttr(true),
        hidden: !external,
        "data-disabled": dataAttr(disabled),
      }),

    getExternalLabelProps: (): T["element"] =>
      normalize.element({
        ...parts.externalLabel.attrs,
        hidden: !external,
      }),
  };
}

import { getPartId } from "../../machine/ids";
import type { Scope } from "../../machine/scope";

const COMPONENT = "link";

export function getRootId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "root");
}

export function getRootEl(scope: Scope): HTMLElement | null {
  return scope.getById(getRootId(scope));
}

/**
 * A link is smaller than a button and still needs a machine, for the two things
 * a pure `connect` cannot carry: `data-focus-source` is the modality captured
 * at the moment focus lands and frozen until it leaves, and `data-pressed` has
 * to survive the finger sliding off the control and coming back — pointer
 * capture, an effect with a cleanup.
 *
 * What it does not need is button's activation arbitration. Activation is the
 * browser's: a real `<a>` turns Enter into a click and a pointer sequence ends
 * in a compatibility click, both of which arrive as `ROOT.CLICK`. Only a
 * substituted root, where Enter produces no native click, gets `ROOT.PRESS`
 * synthesised by the connect — the two paths are mutually exclusive by
 * construction, so `invokeOnPress` never has to pick one.
 *
 * The press primitive runs with its keyboard mode off, always: that mode is
 * shaped like a button — it activates on Space and calls `preventDefault(" ")`
 * — which is exactly wrong for a link, where Space must keep scrolling the
 * page. The primitive only serves the pointer visual here.
 */

import { trackPress } from "../../interaction/press";
import { createMachine } from "../../machine/create-machine";
import type { Machine } from "../../machine/types";
import { getInputModality, trackInputModality } from "../../nav";
import type { InputModality } from "../../types";
import { getRootEl } from "./link.dom";
import type { LinkSchema } from "./link.types";

export const machine: Machine<LinkSchema> = createMachine<LinkSchema>({
  props({ props }) {
    const variant = props.variant ?? "tint";
    return {
      external: false,
      current: false,
      disabled: false,
      focusableWhenDisabled: false,
      nativeLink: true,
      ...props,
      variant,
      // Resolved after `variant`: a plain link without an underline is not
      // identifiable as a link at all (WCAG 1.4.1).
      underline: props.underline ?? (variant === "plain" ? "always" : "hover"),
    };
  },

  context({ bindable }) {
    return {
      pressed: bindable<boolean>(() => ({ defaultValue: false })),
      focusSource: bindable<InputModality | null>(() => ({ defaultValue: null })),
    };
  },

  initialState() {
    return "idle";
  },

  effects: ["trackModality", "trackPointerPress"],

  watch({ prop, track, action }) {
    // A link disabled mid-press must not stay stuck in `data-pressed`.
    track(
      () => [prop("disabled")],
      () => action(["clearPressed"]),
    );
  },

  on: {
    "ROOT.CLICK": { guard: "isInteractive", actions: ["invokeOnPress"] },
    "ROOT.PRESS": { guard: "isInteractive", actions: ["invokeOnPress"] },
    "ROOT.PRESS_START": { guard: "isInteractive", actions: ["setPressed"] },
    "ROOT.PRESS_END": { actions: ["clearPressed"] },
    "ROOT.FOCUS": { target: "focused", actions: ["captureFocusSource"] },
  },

  states: {
    idle: {},
    focused: {
      exit: ["clearFocusSource", "clearPressed"],
      on: { "ROOT.BLUR": { target: "idle" } },
    },
  },

  implementations: {
    guards: {
      isInteractive: ({ prop }) => !prop("disabled"),
    },

    actions: {
      invokeOnPress({ prop, event }) {
        // No arbitration, only narrowing: ROOT.PRESS is only ever sent for a
        // substituted root and ROOT.CLICK covers everything else, so accepting
        // both cannot double-fire — see the note at the top of the file.
        if (event.type !== "ROOT.CLICK" && event.type !== "ROOT.PRESS") return;
        prop("onPress")?.({ originalEvent: event.originalEvent });
      },
      setPressed({ context }) {
        context.set("pressed", true);
      },
      clearPressed({ context }) {
        context.set("pressed", false);
      },
      captureFocusSource({ context, scope }) {
        context.set("focusSource", getInputModality(scope.getDoc()));
      },
      clearFocusSource({ context }) {
        context.set("focusSource", null);
      },
    },

    effects: {
      // No listener: the source is read once, when focus lands, so a modality
      // change no longer has to reach every mounted control. Holding the handle
      // is the whole job — the tracker has to be running before the first Tab.
      trackModality({ scope }) {
        return trackInputModality(scope.getDoc());
      },

      trackPointerPress({ scope, prop, send }) {
        return trackPress(getRootEl(scope), {
          isDisabled: () => prop("disabled"),
          // Always off, and no `onPress` either: activation never comes from
          // the primitive — see the note at the top of the file.
          keyboard: false,
          onPressStart: () => send({ type: "ROOT.PRESS_START" }),
          onPressEnd: () => send({ type: "ROOT.PRESS_END" }),
          onPressCancel: () => send({ type: "ROOT.PRESS_END" }),
        });
      },
    },
  },
});

import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema } from "../../machine/types";
import type { Direction, InputModality } from "../../types";

/** `tint` paints `--sui-color-link`; `plain` rides `currentColor`. */
export type LinkVariant = "tint" | "plain";

export type LinkUnderline = "hover" | "always" | "none";

/** Values of `aria-current`; `true` serialises as `aria-current="true"`. */
export type LinkCurrent = boolean | "page" | "step" | "location" | "date" | "time";

export interface LinkPressDetails {
  readonly originalEvent: Event;
}

export interface LinkMachineProps {
  readonly dir?: Direction | undefined;
  /**
   * Stripped from the DOM while `disabled` — a prevented attribute can still be
   * reached around (middle click, the context menu), an absent href cannot.
   */
  readonly href?: string | undefined;
  readonly target?: string | undefined;
  readonly rel?: string | undefined;
  /**
   * An outbound link: `target="_blank"` + `rel="noopener noreferrer"` by
   * default, `data-external` on the root, and the externalIcon/externalLabel
   * parts come alive.
   */
  readonly external?: boolean | undefined;
  /** `aria-current` — the router's hook for "you are here". */
  readonly current?: LinkCurrent | undefined;
  readonly variant?: LinkVariant | undefined;
  /**
   * Defaults to `"hover"` for `tint` and `"always"` for `plain`: a link in the
   * colour of its surrounding text with no underline is not identifiable as a
   * link at all (WCAG 1.4.1).
   */
  readonly underline?: LinkUnderline | undefined;
  readonly disabled?: boolean | undefined;
  /** Keeps the link reachable on Tab while disabled (`tabIndex 0` + `role="link"`). */
  readonly focusableWhenDisabled?: boolean | undefined;
  /**
   * False when the root is not a real `<a>` (a `span role="link"`). The adapter
   * infers it from what it renders; it decides who synthesises Enter.
   */
  readonly nativeLink?: boolean | undefined;
  /**
   * Auxiliary (analytics, JS-only links without an href). It never replaces the
   * native or router navigation and never calls `preventDefault`.
   */
  readonly onPress?: ((details: LinkPressDetails) => void) | undefined;
}

/** What the machine sees once the defaults are applied. */
export interface ResolvedLinkMachineProps extends LinkMachineProps {
  readonly external: boolean;
  readonly current: LinkCurrent;
  readonly variant: LinkVariant;
  readonly underline: LinkUnderline;
  readonly disabled: boolean;
  readonly focusableWhenDisabled: boolean;
  readonly nativeLink: boolean;
}

export interface LinkSchema extends MachineSchema {
  state: "idle" | "focused";
  props: ResolvedLinkMachineProps;
  context: { pressed: boolean; focusSource: InputModality | null };
  event:
    | { type: "ROOT.CLICK"; originalEvent: Event }
    | { type: "ROOT.PRESS"; originalEvent: Event }
    | { type: "ROOT.PRESS_START" }
    | { type: "ROOT.PRESS_END" }
    | { type: "ROOT.FOCUS" }
    | { type: "ROOT.BLUR" };
  action:
    | "invokeOnPress"
    | "setPressed"
    | "clearPressed"
    | "captureFocusSource"
    | "clearFocusSource";
  guard: "isInteractive";
  effect: "trackModality" | "trackPointerPress";
}

export interface LinkApi<T extends PropTypes = PropTypes> {
  readonly disabled: boolean;
  readonly external: boolean;
  readonly current: LinkCurrent;
  /** True between press-start and press-end — what drives the press dim. */
  readonly pressed: boolean;
  /** The modality focus arrived under, or `null` while this is not focused. */
  readonly focusSource: InputModality | null;
  /** True only while focused, and only when that source warrants a ring. */
  readonly focusVisible: boolean;
  getRootProps(): T["a"];
  getExternalIconProps(): T["element"];
  getExternalLabelProps(): T["element"];
}

/**
 * `<Link href="…">…</Link>` — the anchor and the two companion parts of the
 * outbound affordance, in the one order the accessible name depends on: the
 * text, then the glyph, then the sr-only wording. Three nodes at most, no
 * collection, and the smallest composed layer in the navigation family.
 *
 * **`asChild` is omitted, and that is a correctness fix rather than tidiness.**
 * `LinkRoot` infers `nativeLink` from what it is about to render, and the two
 * branches of that inference read different things: `render` is read as the
 * element it is, while `asChild` sends `isNativeLink` to the root's *children*
 * instead (`link.tsx`, `onlyElement` → `Children.count(children) === 1`). In the
 * composed form those children are the layer's — the consumer's text plus
 * whichever of the two companion parts were asked for — so the inference would be
 * answering about a tree the consumer never wrote: one child on the minimal form,
 * three on the outbound one, and either way an element that is not what
 * `asChild` was pointed at. `render` is unaffected and stays, which is also the
 * substitution that matters here: a router's `Link` renders an `<a>` and the
 * inference is written to lean that way.
 *
 * **Both companion parts are gated on the consumer's content, never on
 * `external`.** That is the parts form's own behaviour — `getExternalIconProps`
 * and `getExternalLabelProps` each write `hidden: !external`, so the machine is
 * what makes them appear and disappear — and keeping placement independent of the
 * flag preserves the property this component's page states: toggling `external`
 * on a mounted link changes an attribute and remounts nothing.
 *
 * **`icon` is placed only once it is supplied**, and that one is about pixels
 * rather than semantics. `_link.scss` gives `link:external-icon` a 0.65em box and
 * a 0.3em inline margin and draws nothing inside it — there is no `:empty`
 * default here, unlike the chevrons and checkmarks elsewhere, because the
 * outbound mark is the one symbol this library never picked for the consumer.
 * Placed empty it is a third of an em of visible nothing in the middle of a
 * sentence. Hence the case-(c) guard: React renders `false` as nothing, so
 * `icon={isExternal && <ArrowUpRight/>}` would otherwise reach the part as a
 * falsy child rather than as an absent slot.
 *
 * **`externalLabel` is a name, not a slot.** `getExternalLabelProps` writes the
 * part token and `hidden` and nothing that says anything; the words are the
 * consumer's, and so is their language (WCAG G201 — warn before a new window
 * opens; H83 — say it in the link's own text). The part is `sr-only` in the sheet
 * and lives *inside* the anchor, so the wording joins the accessible name with no
 * `aria-describedby` to keep in sync. The empty string counts as absent, the way
 * `Dialog.closeLabel` and `MenuContent.cancelLabel` already read it: an empty
 * sr-only span adds nothing to the name and one node to every link on the page.
 */

import type { ReactNode } from "react";
import type { PartProps } from "../../create-part";
import { LinkExternalIcon, LinkExternalLabel, LinkRoot, type UseLinkProps } from "./link";

/**
 * The escape hatch, applied **last** on both parts: what the layer defaults is a
 * default, and the consumer's entry wins over it — including over the `hidden`
 * and `aria-hidden` the machine writes itself. No `root` key, because the root's
 * props *are* the composed props; and no `Omit` of `id` or of an IDREF, unlike the
 * collections, since each of these two parts is placed once — a fixed id here is a
 * fixed id and not the same one repeated down a list.
 */
export interface LinkParts {
  readonly externalIcon?: PartProps<"span"> | undefined;
  readonly externalLabel?: PartProps<"span"> | undefined;
}

export interface LinkComposedProps
  extends UseLinkProps,
    Omit<PartProps<"a", UseLinkProps>, "children" | "asChild"> {
  /** The link text — what names the link, and the only thing that can. */
  readonly children?: ReactNode;
  /** The outbound glyph: an inline SVG, never a text character — see above. */
  readonly icon?: ReactNode;
  /**
   * The "opens in a new tab" wording, hidden visually and read as part of the
   * name. Empty counts as absent.
   */
  readonly externalLabel?: string | undefined;
  readonly parts?: LinkParts | undefined;
}

export function Link(props: LinkComposedProps): ReactNode {
  const { children, icon, externalLabel, parts, ...root } = props;

  return (
    <LinkRoot {...root}>
      {children}
      {/* Case (c): the sheet sizes this box and draws nothing in it, so a falsy
          slot placed anyway is 0.65em plus a 0.3em margin of visible nothing
          inside a run of text. */}
      {icon == null || icon === false ? null : (
        <LinkExternalIcon {...parts?.externalIcon}>{icon}</LinkExternalIcon>
      )}
      {externalLabel == null || externalLabel === "" ? null : (
        <LinkExternalLabel {...parts?.externalLabel}>{externalLabel}</LinkExternalLabel>
      )}
    </LinkRoot>
  );
}

export type {
  LinkCurrent,
  LinkMachineProps,
  LinkPressDetails,
  LinkUnderline,
  LinkVariant,
} from "@standarui/core/link";
export { Link, type LinkComposedProps, type LinkParts } from "./composed";
export {
  type LinkApi,
  LinkExternalIcon,
  LinkExternalLabel,
  LinkRoot,
  type LinkRootProps,
  type UseLinkProps,
  useLink,
} from "./link";

/**
 * The React layer of the link: a root that owns the machine, two companion parts
 * for the outbound affordance, and `useLink` underneath for anyone who would
 * rather place the props themselves.
 *
 * `nativeLink` is inferred here because this is the only layer that knows what is
 * about to be rendered, and the inference deliberately leans the other way from
 * the button's. There, anything substituted is assumed *not* to be a button; here
 * the overwhelming substitution is a router's `Link`, which renders an `<a>`. The
 * asymmetry is a cost comparison, not a preference:
 *
 *   - guessing `false` on something that really is an `<a>` fires `onPress` twice
 *     on Enter — the synthesised `ROOT.PRESS` plus the browser's own click;
 *   - guessing `true` on a `<div>` costs the link role and Enter, on a root
 *     nobody writes by accident and which the `nativeLink` prop overrides.
 *
 * So only an intrinsic element that is *not* `"a"` answers false. A component —
 * a router's link, a styled wrapper — answers true.
 */

import * as link from "@standarui/core/link";
import { Children, isValidElement, type ReactNode } from "react";
import { createPart, type PartProps } from "../../create-part";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { createPartContext } from "../../part-context";
import { splitProps } from "../../split-props";
import { type MachineRuntimeProps, useMachine } from "../../use-machine";
import { type RenderProp, useRender } from "../../use-render";

export type LinkApi = link.LinkApi<ReactPropTypes>;

const LinkContext = createPartContext<LinkApi>("Link");

export interface UseLinkProps extends link.LinkMachineProps, MachineRuntimeProps {}

/** The api behind the components — prop getters, state, nothing rendered. */
export function useLink(props: UseLinkProps): LinkApi {
  return link.connect(useMachine(link.machine, props), normalizeProps);
}

const MACHINE_PROPS = [
  "id",
  "ids",
  "getRootNode",
  "dir",
  "href",
  "target",
  "rel",
  "external",
  "current",
  "variant",
  "underline",
  "disabled",
  "focusableWhenDisabled",
  "nativeLink",
  "onPress",
] as const;

export interface LinkRootProps extends UseLinkProps, PartProps<"a", UseLinkProps> {}

function onlyElement(children: ReactNode): ReactNode {
  // `Children.only` throws on anything but exactly one child, and a root with two
  // children under `asChild` is the consumer's bug to hear about from `useRender`,
  // not a reason for this inference to blow up first.
  return Children.count(children) === 1 ? Children.toArray(children)[0] : undefined;
}

/** `false` only when the element being rendered is an intrinsic that is not `<a>`. */
function isNativeLink(
  render: RenderProp | undefined,
  asChild: boolean | undefined,
  children: ReactNode,
): boolean {
  const target = asChild === true ? onlyElement(children) : render;
  if (target === undefined || !isValidElement(target)) return true;
  return typeof target.type === "string" ? target.type === "a" : true;
}

export function LinkRoot(props: LinkRootProps): ReactNode {
  const [machineProps, rest] = splitProps(props, MACHINE_PROPS);
  const { render, asChild, children, ...elementProps } = rest;

  const api = useLink({
    nativeLink: isNativeLink(render, asChild, children),
    ...machineProps,
  });

  return (
    <LinkContext.Provider value={api}>
      {useRender({
        render,
        asChild,
        element: "a",
        props: api.getRootProps(),
        elementProps,
        children,
      })}
    </LinkContext.Provider>
  );
}

/**
 * Wraps the outbound glyph. Its children are the consumer's own inline SVG — a
 * text character would sit on its baseline rather than in the middle of its box,
 * which is not the same shape at every font size.
 */
export const LinkExternalIcon: (props: PartProps<"span">) => ReactNode = createPart(LinkContext, {
  name: "LinkExternalIcon",
  element: "span",
  props: (api) => api.getExternalIconProps(),
});

/**
 * The "opens in a new tab" wording, inside the anchor so it joins the accessible
 * name with no `aria-describedby` to keep in sync. The stylesheet hides it
 * visually; the text itself is the consumer's, and so is its language.
 */
export const LinkExternalLabel: (props: PartProps<"span">) => ReactNode = createPart(LinkContext, {
  name: "LinkExternalLabel",
  element: "span",
  props: (api) => api.getExternalLabelProps(),
});
